        int n = sc.nextInt();
        for (int i = 0; i < n; i++) {
            insert(root, sc.next());
        }
        int q = sc.nextInt();
        for (int i = 0; i < q; i++) {
            String word = sc.next();
            System.out.println(word + ": " + search(root, word));
        }
    }

    static void insert(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int i = c - 'a';
            if (node.children[i] == null) {
                node.children[i] = new TrieNode();
            }
            node = node.children[i];
        }
        node.isWord = true;
    }

    static boolean search(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            node = node.children[c - 'a'];
            if (node == null) {
                return false;
            }
        }
        return node.isWord;
    }
}

